package pipedrive

import "net/http"

type Config struct {
	// BaseURL is the API origin requests are sent to. When set, credentials
	// from Auth are only attached to requests targeting this origin (scheme
	// and host), including redirect hops — a cross-origin redirect target
	// never receives them. When empty, Auth applies to every request made
	// through the client, but a redirect that leaves the initial request's
	// origin still suppresses credentials on that hop.
	//
	// The value must be an absolute URL with a scheme and host, e.g.
	// "https://api.pipedrive.com". A value that lacks either fails closed:
	// credentials are withheld from every request rather than sent
	// somewhere unintended, which surfaces as authentication errors from
	// the API. v1/v2 NewClient reject such values; NewHTTPClient cannot
	// return an error, so it withholds silently.
	BaseURL string

	// OAuthBaseURL is the origin the v1 OAuth service uses for authorize
	// URLs and token exchange/refresh. Empty uses the production default
	// (https://oauth.pipedrive.com). Requests to it authenticate with
	// explicit client credentials; Auth is never attached.
	OAuthBaseURL string

	HTTPClient *http.Client

	Middleware []Middleware

	RetryPolicy *RetryPolicy

	// MaxResponseSize caps successful response bodies in bytes.
	// Zero uses the default 64 MiB cap. Negative values disable the cap.
	MaxResponseSize int64

	UserAgent string
	Auth      AuthProvider
}

func NewHTTPClient(cfg Config) *http.Client {
	base := cfg.HTTPClient
	if base == nil {
		base = http.DefaultClient
	}

	clone := new(http.Client)
	*clone = *base

	transport := clone.Transport
	if transport == nil {
		transport = http.DefaultTransport
	}

	origin := authOriginFromBaseURL(cfg.BaseURL)

	middleware := make([]Middleware, 0, len(cfg.Middleware)+2)
	middleware = append(middleware, cfg.Middleware...)
	if cfg.UserAgent != "" {
		middleware = append(middleware, userAgentMiddleware(cfg.UserAgent))
	}
	if cfg.Auth != nil {
		middleware = append(middleware, authMiddleware(cfg.Auth, origin))
	}

	// Catches credential headers set directly on the request (for example
	// through WithHeader), which the auth middleware never sees, and marks
	// off-scope hops so the middleware does not re-attach Auth credentials.
	clone.CheckRedirect = redirectCredentialGuard(origin, base.CheckRedirect)

	transport = newResponseLimitTransport(transport, cfg.MaxResponseSize)
	transport = chainMiddleware(transport, middleware)

	policy := cfg.RetryPolicy
	if policy == nil {
		p := DefaultRetryPolicy()
		policy = &p
	}
	transport = newRetryTransport(transport, *policy, retryTransportOptions{})

	clone.Transport = transport
	return clone
}

package pipedrive

import (
	"context"
	"errors"
	"io"
	"net/http"
	"strings"
	"testing"
	"time"
)

func TestRetryTransport_RetriesOnRetryableStatus(t *testing.T) {
	t.Parallel()

	var calls int
	next := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		calls++
		status := 502
		if calls == 2 {
			status = 200
		}
		return &http.Response{
			StatusCode: status,
			Header:     make(http.Header),
			Body:       io.NopCloser(strings.NewReader("")),
			Request:    req,
		}, nil
	})

	var sleeps []time.Duration
	sleep := func(_ context.Context, d time.Duration) error {
		sleeps = append(sleeps, d)
		return nil
	}

	policy := DefaultRetryPolicy()
	policy.BaseDelay = 1 * time.Millisecond
	policy.MaxDelay = 1 * time.Millisecond
	policy.Jitter = func(d time.Duration) time.Duration { return d }

	rt := newRetryTransport(next, policy, retryTransportOptions{
		sleep: sleep,
		now:   func() time.Time { return time.Unix(0, 0).UTC() },
	})

	req, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, "https://example.test", nil)
	resp, err := rt.RoundTrip(req)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	_ = resp.Body.Close()

	if calls != 2 {
		t.Fatalf("expected 2 calls, got %d", calls)
	}
	if resp.StatusCode != 200 {
		t.Fatalf("expected status 200, got %d", resp.StatusCode)
	}
	if len(sleeps) != 1 {
		t.Fatalf("expected 1 sleep, got %d", len(sleeps))
	}
	if sleeps[0] != 1*time.Millisecond {
		t.Fatalf("expected sleep 1ms, got %s", sleeps[0])
	}
}

func TestRetryTransport_RespectsRetryAfter(t *testing.T) {
	t.Parallel()

	var calls int
	next := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		calls++
		h := make(http.Header)
		if calls == 1 {
			h.Set("Retry-After", "2")
			return &http.Response{
				StatusCode: 429,
				Header:     h,
				Body:       io.NopCloser(strings.NewReader("")),
				Request:    req,
			}, nil
		}
		return &http.Response{
			StatusCode: 200,
			Header:     h,
			Body:       io.NopCloser(strings.NewReader("")),
			Request:    req,
		}, nil
	})

	var sleeps []time.Duration
	sleep := func(_ context.Context, d time.Duration) error {
		sleeps = append(sleeps, d)
		return nil
	}

	policy := DefaultRetryPolicy()
	policy.Jitter = func(d time.Duration) time.Duration { return d }

	rt := newRetryTransport(next, policy, retryTransportOptions{
		sleep: sleep,
		now:   func() time.Time { return time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC) },
	})

	req, _ := http.NewRequestWithContext(context.Background(), http.MethodPost, "https://example.test", nil)
	resp, err := rt.RoundTrip(req)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	_ = resp.Body.Close()

	if calls != 2 {
		t.Fatalf("expected 2 calls, got %d", calls)
	}
	if len(sleeps) != 1 || sleeps[0] != 2*time.Second {
		t.Fatalf("expected sleep 2s, got %v", sleeps)
	}
}

func TestRetryTransport_CapsServerRetryAfter(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name       string
		retryAfter string
		wantSleep  time.Duration
	}{
		{name: "beyond cap", retryAfter: "3600", wantSleep: time.Minute},
		{name: "overflowing seconds", retryAfter: "9999999999999999", wantSleep: time.Minute},
		{name: "within cap beyond MaxDelay", retryAfter: "30", wantSleep: 30 * time.Second},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			var calls int
			next := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
				calls++
				h := make(http.Header)
				if calls == 1 {
					h.Set("Retry-After", tt.retryAfter)
					return &http.Response{
						StatusCode: 429,
						Header:     h,
						Body:       io.NopCloser(strings.NewReader("")),
						Request:    req,
					}, nil
				}
				return &http.Response{
					StatusCode: 200,
					Header:     h,
					Body:       io.NopCloser(strings.NewReader("")),
					Request:    req,
				}, nil
			})

			var sleeps []time.Duration
			policy := DefaultRetryPolicy()
			policy.Jitter = func(d time.Duration) time.Duration { return d }

			rt := newRetryTransport(next, policy, retryTransportOptions{
				sleep: func(_ context.Context, d time.Duration) error {
					sleeps = append(sleeps, d)
					return nil
				},
				now: func() time.Time { return time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC) },
			})

			req, _ := http.NewRequestWithContext(context.Background(), http.MethodPost, "https://example.test", nil)
			resp, err := rt.RoundTrip(req)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			_ = resp.Body.Close()

			if len(sleeps) != 1 || sleeps[0] != tt.wantSleep {
				t.Fatalf("expected sleep %s, got %v", tt.wantSleep, sleeps)
			}
		})
	}
}

func TestParseRetryAfter_OverflowingSecondsSaturate(t *testing.T) {
	t.Parallel()

	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)
	got := parseRetryAfter("9999999999999999", now)
	if got <= 0 {
		t.Fatalf("expected positive saturated duration, got %s", got)
	}
}

func TestRetryTransport_CanBeDisabledPerRequest(t *testing.T) {
	t.Parallel()

	var calls int
	next := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		calls++
		return &http.Response{
			StatusCode: 503,
			Header:     make(http.Header),
			Body:       io.NopCloser(strings.NewReader("")),
			Request:    req,
		}, nil
	})

	rt := newRetryTransport(next, DefaultRetryPolicy(), retryTransportOptions{
		sleep: func(context.Context, time.Duration) error { return nil },
		now:   time.Now,
	})

	req, _ := http.NewRequestWithContext(withNoRetry(context.Background()), http.MethodGet, "https://example.test", nil)
	resp, err := rt.RoundTrip(req)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	_ = resp.Body.Close()

	if calls != 1 {
		t.Fatalf("expected 1 call, got %d", calls)
	}
	if resp.StatusCode != 503 {
		t.Fatalf("expected status 503, got %d", resp.StatusCode)
	}
}

func TestRetryTransport_DoesNotRetryWhenBodyNotReplayable(t *testing.T) {
	t.Parallel()

	var calls int
	next := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		calls++
		return &http.Response{
			StatusCode: 502,
			Header:     make(http.Header),
			Body:       io.NopCloser(strings.NewReader("")),
			Request:    req,
		}, nil
	})

	rt := newRetryTransport(next, DefaultRetryPolicy(), retryTransportOptions{
		sleep: func(context.Context, time.Duration) error { return nil },
		now:   time.Now,
	})

	body := io.NopCloser(strings.NewReader("payload"))
	req, _ := http.NewRequestWithContext(context.Background(), http.MethodPost, "https://example.test", body)
	resp, err := rt.RoundTrip(req)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	_ = resp.Body.Close()

	if calls != 1 {
		t.Fatalf("expected 1 call, got %d", calls)
	}
}

func TestRetryTransport_UsesPerRequestRetryPolicyOverride(t *testing.T) {
	t.Parallel()

	var calls int
	next := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		calls++
		status := 502
		if calls == 3 {
			status = 200
		}
		return &http.Response{
			StatusCode: status,
			Header:     make(http.Header),
			Body:       io.NopCloser(strings.NewReader("")),
			Request:    req,
		}, nil
	})

	sleep := func(_ context.Context, _ time.Duration) error { return nil }
	policy := RetryPolicy{MaxAttempts: 2, BaseDelay: 0, Jitter: func(d time.Duration) time.Duration { return d }}
	rt := newRetryTransport(next, policy, retryTransportOptions{
		sleep: sleep,
		now:   time.Now,
	})

	override := RetryPolicy{MaxAttempts: 3, BaseDelay: 0, Jitter: func(d time.Duration) time.Duration { return d }}
	ctx := withRetryPolicy(context.Background(), override)
	req, _ := http.NewRequestWithContext(ctx, http.MethodGet, "https://example.test", nil)

	resp, err := rt.RoundTrip(req)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	_ = resp.Body.Close()

	if calls != 3 {
		t.Fatalf("expected 3 calls, got %d", calls)
	}
	if resp.StatusCode != 200 {
		t.Fatalf("expected status 200, got %d", resp.StatusCode)
	}
}

func TestRetryTransport_StopsAfterExactMaxAttempts(t *testing.T) {
	t.Parallel()

	var calls int
	next := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		calls++
		return &http.Response{
			StatusCode: 502,
			Header:     make(http.Header),
			Body:       io.NopCloser(strings.NewReader("")),
			Request:    req,
		}, nil
	})

	rt := newRetryTransport(next, RetryPolicy{MaxAttempts: 2}, retryTransportOptions{
		sleep: func(context.Context, time.Duration) error { return nil },
		now:   time.Now,
	})

	req, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, "https://example.test", nil)
	resp, err := rt.RoundTrip(req)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	_ = resp.Body.Close()

	if calls != 2 {
		t.Fatalf("expected 2 calls, got %d", calls)
	}
	if resp.StatusCode != 502 {
		t.Fatalf("expected status 502, got %d", resp.StatusCode)
	}
}

func TestRetryTransport_NilRequestReturnsError(t *testing.T) {
	t.Parallel()

	rt := newRetryTransport(roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		t.Fatalf("unexpected call to next transport")
		return nil, nil
	}), DefaultRetryPolicy(), retryTransportOptions{})

	_, err := rt.RoundTrip(nil)
	if err == nil {
		t.Fatalf("expected error")
	}
	if err.Error() != "pipedrive: nil request" {
		t.Fatalf("unexpected error: %v", err)
	}
}

func TestRetryHelpers(t *testing.T) {
	t.Parallel()

	for _, method := range []string{
		http.MethodGet,
		http.MethodHead,
		http.MethodPut,
		http.MethodDelete,
		http.MethodOptions,
		http.MethodTrace,
	} {
		if !isIdempotentMethod(method) {
			t.Fatalf("expected %s to be idempotent", method)
		}
	}
	for _, method := range []string{http.MethodPost, http.MethodPatch, "CUSTOM"} {
		if isIdempotentMethod(method) {
			t.Fatalf("expected %s to be non-idempotent", method)
		}
	}

	if got := fullJitter(0); got != 0 {
		t.Fatalf("fullJitter(0) = %s, want 0", got)
	}
	if got := fullJitter(-time.Second); got != 0 {
		t.Fatalf("fullJitter(-1s) = %s, want 0", got)
	}
	for i := 0; i < 20; i++ {
		if got := fullJitter(10 * time.Millisecond); got < 0 || got >= 10*time.Millisecond {
			t.Fatalf("fullJitter out of range: %s", got)
		}
	}
}

func TestSleepWithContext_ReturnsOnCancel(t *testing.T) {
	t.Parallel()

	if err := sleepWithContext(context.Background(), 0); err != nil {
		t.Fatalf("zero sleep error: %v", err)
	}

	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	err := sleepWithContext(ctx, time.Hour)
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("expected context canceled, got %v", err)
	}
}

func TestSanitizeRetryPolicy_ClampsInvalidValues(t *testing.T) {
	t.Parallel()

	policy := sanitizeRetryPolicy(RetryPolicy{
		MaxAttempts: -3,
		BaseDelay:   -time.Second,
		MaxDelay:    0,
		Jitter:      nil,
	})

	if policy.MaxAttempts != 1 {
		t.Fatalf("expected max attempts 1, got %d", policy.MaxAttempts)
	}
	if policy.BaseDelay != 0 {
		t.Fatalf("expected base delay 0, got %s", policy.BaseDelay)
	}
	if policy.MaxDelay != 0 {
		t.Fatalf("expected max delay 0, got %s", policy.MaxDelay)
	}
	if policy.Jitter == nil {
		t.Fatalf("expected default jitter")
	}
	if got := policy.Jitter(3 * time.Second); got != 3*time.Second {
		t.Fatalf("unexpected default jitter result: %s", got)
	}

	policy = sanitizeRetryPolicy(RetryPolicy{
		MaxAttempts: 2,
		BaseDelay:   time.Second,
		MaxDelay:    -time.Second,
		Jitter:      func(d time.Duration) time.Duration { return d / 2 },
	})
	if policy.MaxDelay != time.Second {
		t.Fatalf("expected max delay to default to base delay, got %s", policy.MaxDelay)
	}
	if got := policy.Jitter(4 * time.Second); got != 2*time.Second {
		t.Fatalf("unexpected custom jitter result: %s", got)
	}
}

