package pipedrive

import (
	"context"
	"io"
	"net/http"
)

const defaultMaxResponseSize int64 = 64 << 20

// errorResponseBodyLimit caps how much of a non-2xx response body is kept
// for error reporting. Unlike the success-path limit, exceeding it is not
// an error: reads simply stop at the cap. Per-request overrides do not
// apply — a hostile or broken server must never make the client buffer an
// unbounded error payload.
const errorResponseBodyLimit int64 = 1 << 20

type responseSizeLimitOption struct {
	set       bool
	limit     int64
	unlimited bool
}

type responseSizeLimitKey struct{}

func withResponseSizeLimit(ctx context.Context, opt responseSizeLimitOption) context.Context {
	return context.WithValue(ctx, responseSizeLimitKey{}, opt)
}

func responseSizeLimitFromContext(ctx context.Context) (responseSizeLimitOption, bool) {
	opt, ok := ctx.Value(responseSizeLimitKey{}).(responseSizeLimitOption)
	return opt, ok
}

func normalizeResponseSizeLimit(limit int64) int64 {
	switch {
	case limit < 0:
		return -1
	case limit == 0:
		return defaultMaxResponseSize
	default:
		return limit
	}
}

func effectiveResponseSizeLimit(ctx context.Context, defaultLimit int64) int64 {
	limit := normalizeResponseSizeLimit(defaultLimit)

	override, ok := responseSizeLimitFromContext(ctx)
	if !ok || !override.set {
		return limit
	}
	if override.unlimited {
		return -1
	}
	return normalizeResponseSizeLimit(override.limit)
}

type responseLimitTransport struct {
	next         http.RoundTripper
	defaultLimit int64
}

func newResponseLimitTransport(next http.RoundTripper, defaultLimit int64) http.RoundTripper {
	if next == nil {
		next = http.DefaultTransport
	}
	return &responseLimitTransport{
		next:         next,
		defaultLimit: defaultLimit,
	}
}

func (t *responseLimitTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	resp, err := t.next.RoundTrip(req)
	if err != nil || resp == nil || resp.Body == nil {
		return resp, err
	}
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		resp.Body = &truncatingReadCloser{
			reader: io.LimitReader(resp.Body, errorResponseBodyLimit),
			closer: resp.Body,
		}
		return resp, nil
	}

	limit := effectiveResponseSizeLimit(req.Context(), t.defaultLimit)
	if limit < 0 {
		return resp, nil
	}

	resp.Body = &responseLimitReadCloser{
		body:      resp.Body,
		limit:     limit,
		remaining: limit,
	}
	return resp, nil
}

type responseLimitReadCloser struct {
	body      io.ReadCloser
	limit     int64
	remaining int64
}

func (r *responseLimitReadCloser) Read(p []byte) (int, error) {
	if len(p) == 0 {
		return r.body.Read(p)
	}
	if r.remaining <= 0 {
		var probe [1]byte
		n, err := r.body.Read(probe[:])
		switch {
		case n == 0 && err == io.EOF:
			return 0, io.EOF
		case n > 0 || err == nil:
			return 0, &ResponseTooLargeError{Limit: r.limit}
		default:
			return 0, err
		}
	}

	if int64(len(p)) > r.remaining {
		p = p[:int(r.remaining)]
	}

	n, err := r.body.Read(p)
	r.remaining -= int64(n)
	return n, err
}

func (r *responseLimitReadCloser) Close() error {
	return r.body.Close()
}

type truncatingReadCloser struct {
	reader io.Reader
	closer io.Closer
}

func (t *truncatingReadCloser) Read(p []byte) (int, error) {
	return t.reader.Read(p)
}

func (t *truncatingReadCloser) Close() error {
	return t.closer.Close()
}

package pipedrive

import (
	"context"
	"net/http"
)

type RequestEditorFunc func(ctx context.Context, req *http.Request) error

type RequestOption func(*requestOptions)

type requestOptions struct {
	headers map[string]string
	editors []RequestEditorFunc

	noRetry bool

	retryPolicy       *RetryPolicy
	responseSizeLimit responseSizeLimitOption
}

func WithHeader(key, value string) RequestOption {
	return func(o *requestOptions) {
		if o.headers == nil {
			o.headers = make(map[string]string)
		}
		o.headers[key] = value
	}
}

func WithRequestEditor(fn RequestEditorFunc) RequestOption {
	return func(o *requestOptions) {
		if fn == nil {
			return
		}
		o.editors = append(o.editors, fn)
	}
}

func WithNoRetry() RequestOption {
	return func(o *requestOptions) {
		o.noRetry = true
	}
}

func WithRetryPolicy(policy RetryPolicy) RequestOption {
	return func(o *requestOptions) {
		o.retryPolicy = &policy
	}
}

func WithResponseSizeLimit(limit int64) RequestOption {
	return func(o *requestOptions) {
		o.responseSizeLimit = responseSizeLimitOption{
			set:   true,
			limit: limit,
		}
	}
}

func WithNoResponseSizeLimit() RequestOption {
	return func(o *requestOptions) {
		o.responseSizeLimit = responseSizeLimitOption{
			set:       true,
			unlimited: true,
		}
	}
}

func ApplyRequestOptions(ctx context.Context, opts ...RequestOption) (context.Context, []RequestEditorFunc) {
	if ctx == nil {
		ctx = context.Background()
	}

	var o requestOptions
	for _, opt := range opts {
		if opt == nil {
			continue
		}
		opt(&o)
	}

	if o.noRetry {
		ctx = withNoRetry(ctx)
	}
	if o.retryPolicy != nil {
		ctx = withRetryPolicy(ctx, *o.retryPolicy)
	}
	if o.responseSizeLimit.set {
		ctx = withResponseSizeLimit(ctx, o.responseSizeLimit)
	}

	editors := make([]RequestEditorFunc, 0, len(o.editors)+1)
	if len(o.headers) > 0 {
		headers := make(map[string]string, len(o.headers))
		for k, v := range o.headers {
			headers[k] = v
		}
		editors = append(editors, func(_ context.Context, req *http.Request) error {
			for k, v := range headers {
				req.Header.Set(k, v)
			}
			return nil
		})
	}
	editors = append(editors, o.editors...)

	return ctx, editors
