package multipartbody

import (
	"io"
	"mime"
	"mime/multipart"
	"net/url"
	"strings"
	"testing"
)

func parseForm(t *testing.T, contentType string, body io.Reader) (url.Values, *multipart.FileHeader) {
	t.Helper()

	mediaType, params, err := mime.ParseMediaType(contentType)
	if err != nil {
		t.Fatalf("parse content type: %v", err)
	}
	if mediaType != "multipart/form-data" {
		t.Fatalf("unexpected media type: %s", mediaType)
	}
	if params["boundary"] == "" {
		t.Fatalf("missing boundary in content type: %s", contentType)
	}

	form, err := multipart.NewReader(body, params["boundary"]).ReadForm(1 << 20)
	if err != nil {
		t.Fatalf("read multipart form: %v", err)
	}
	t.Cleanup(func() { _ = form.RemoveAll() })

	fhs := form.File["file"]
	if len(fhs) != 1 {
		t.Fatalf("expected one file part, got %d", len(fhs))
	}
	return form.Value, fhs[0]
}

func TestNewFile(t *testing.T) {
	t.Parallel()

	contentType, body, err := NewFile("file", "report.pdf", strings.NewReader("pdf bytes"))
	if err != nil {
		t.Fatalf("NewFile error: %v", err)
	}
	if body == nil {
		t.Fatalf("expected body reader")
	}

	values, fh := parseForm(t, contentType, body)
	if len(values) != 0 {
		t.Fatalf("expected no extra form values, got %v", values)
	}
	if fh.Filename != "report.pdf" {
		t.Fatalf("unexpected filename: %q", fh.Filename)
	}
	f, err := fh.Open()
	if err != nil {
		t.Fatalf("open file part: %v", err)
	}
	defer f.Close()
	content, err := io.ReadAll(f)
	if err != nil {
		t.Fatalf("read file part: %v", err)
	}
	if string(content) != "pdf bytes" {
		t.Fatalf("unexpected content: %q", string(content))
	}
}

func TestNewFileWithFields(t *testing.T) {
	t.Parallel()

	fields := url.Values{}
	fields.Set("deal_id", "7")
	fields.Set("lead_id", "0b11da0f-5b1a-43c1-a9b7-9e1f3f2e6d04")

	contentType, body, err := NewFileWithFields("file", "report.pdf", strings.NewReader("pdf bytes"), fields)
	if err != nil {
		t.Fatalf("NewFileWithFields error: %v", err)
	}

	values, fh := parseForm(t, contentType, body)
	if values.Get("deal_id") != "7" {
		t.Fatalf("unexpected deal_id: %q", values.Get("deal_id"))
	}
	if values.Get("lead_id") != "0b11da0f-5b1a-43c1-a9b7-9e1f3f2e6d04" {
		t.Fatalf("unexpected lead_id: %q", values.Get("lead_id"))
	}
	if fh.Filename != "report.pdf" {
		t.Fatalf("unexpected filename: %q", fh.Filename)
	}
	f, err := fh.Open()
	if err != nil {
		t.Fatalf("open file part: %v", err)
	}
	defer f.Close()
	content, err := io.ReadAll(f)
	if err != nil {
		t.Fatalf("read file part: %v", err)
	}
	if string(content) != "pdf bytes" {
		t.Fatalf("unexpected content: %q", string(content))
	}
}

func TestNewFileWithFields_EmptyFieldsMatchesNewFile(t *testing.T) {
	t.Parallel()

	contentType, body, err := NewFileWithFields("file", "report.pdf", strings.NewReader("pdf bytes"), nil)
	if err != nil {
		t.Fatalf("NewFileWithFields error: %v", err)
	}

	values, fh := parseForm(t, contentType, body)
	if len(values) != 0 {
		t.Fatalf("expected no extra form values, got %v", values)
	}
	if fh.Filename != "report.pdf" {
		t.Fatalf("unexpected filename: %q", fh.Filename)
	}
}

func TestNewFile_Errors(t *testing.T) {
	t.Parallel()

	if _, _, err := NewFile("", "report.pdf", strings.NewReader("x")); err == nil {
		t.Fatalf("expected field name error")
	}
	if _, _, err := NewFile("file", "", strings.NewReader("x")); err == nil {
		t.Fatalf("expected file name error")
	}
	if _, _, err := NewFile("file", "report.pdf", nil); err == nil {
		t.Fatalf("expected content error")
	}
	if _, _, err := NewFileWithFields("", "report.pdf", strings.NewReader("x"), nil); err == nil {
		t.Fatalf("expected field name error")
	}
	if _, _, err := NewFileWithFields("file", "", strings.NewReader("x"), nil); err == nil {
		t.Fatalf("expected file name error")
	}
	if _, _, err := NewFileWithFields("file", "report.pdf", nil, nil); err == nil {
		t.Fatalf("expected content error")
	}
}

func TestNewFileWithFields_BodyIsReplayable(t *testing.T) {
	t.Parallel()

	fields := url.Values{}
	fields.Set("deal_id", "7")

	contentType, body, err := NewFileWithFields("file", "report.pdf", strings.NewReader("pdf bytes"), fields)
	if err != nil {
		t.Fatalf("NewFileWithFields error: %v", err)
	}

	first, err := io.ReadAll(body)
	if err != nil {
		t.Fatalf("read body: %v", err)
	}
	if _, err := body.Seek(0, io.SeekStart); err != nil {
		t.Fatalf("seek body: %v", err)
	}
	second, err := io.ReadAll(body)
	if err != nil {
		t.Fatalf("read body again: %v", err)
	}
	if string(first) != string(second) {
		t.Fatalf("expected replayable body")
	}
	if contentType == "" {
		t.Fatalf("expected content type")
	}
}

